<script setup lang="ts">
import {computed,ref} from 'vue'
import {request} from '../api'
import {newId} from '../ids'
import {tasks,effectiveModels,affectedTasks} from './models'
const props=defineProps<{config:any,busy:boolean,dirty:boolean,calls:any[]}>()
const emit=defineEmits<{error:[message:string],test:[model:any]}>()
const presets=ref<any[]>([]),selected=ref(''),fetching=ref(''),lists=ref<Record<string,any[]>>({}),notices=ref<Record<string,string>>({})
const affected=computed(()=>affectedTasks(props.config))
async function loadPresets(){try{presets.value=(await request('/admin/exchange/ai/presets')).items||[]}catch(e){emit('error',String(e))}}
function addService(){try{const preset=presets.value.find(p=>p.id===selected.value);if(!preset)return;props.config.services.push({id:newId(),name:preset.name,kind:preset.kind,base_url:preset.base_url,key_env:preset.kind==='ollama'?null:'LJ_AI_KEY_PRIMARY',enabled:false,timeout_seconds:60})}catch(e){emit('error',String(e))}}
function addModel(service:any,model=''){try{props.config.providers.push({id:newId(),service_id:service.id,name:model||'新模型',kind:service.kind,base_url:service.base_url,key_env:service.key_env,model,enabled:false,text:true,vision:false,reasoning:false,json_mode:true,token_parameter:'auto',system_role:'system',max_output_tokens:2048,daily_requests:20,timeout_seconds:service.timeout_seconds})}catch(e){emit('error',String(e))}}
function removeModel(id:string){props.config.providers=props.config.providers.filter((p:any)=>p.id!==id)}
function modelsFor(id:string){return props.config.providers.filter((p:any)=>p.service_id===id)}
async function fetchModels(service:any){if(props.dirty||!service.enabled||fetching.value)return;fetching.value=service.id;try{const result=await request('/admin/exchange/ai/services/'+service.id+'/models?expected_revision='+props.config.revision);lists.value[service.id]=result.items;notices.value[service.id]=result.notice}catch(e){notices.value[service.id]='列表不可用，可继续手动添加模型。';emit('error',String(e))}finally{fetching.value=''}}
</script>
<template>
<section class="card services"><h2>服务商与模型</h2><p>地址与密钥引用由同一服务商下的模型共享。预设地址可编辑，区域与部署方式请查阅官方文档。所有协议均采用非流式调用；模型能力须按实际服务核对。LM Studio 官方本地地址仅作参考，现有策略禁止其内网访问；需配置公开 HTTPS 网关与密钥引用。本地 Ollama 须由服务端授权精确 Origin 与 IP。</p>
<div class="actions"><button type="button" class="quiet" :disabled="busy" @click="loadPresets">加载服务商预设</button><label>服务商预设<select aria-label="服务商预设" v-model="selected" :disabled="busy"><option value="">选择预设</option><option v-for="p in presets" :key="p.id" :value="p.id">{{p.name}}</option></select></label><a v-if="presets.find(p=>p.id===selected)" :href="presets.find(p=>p.id===selected).docs" target="_blank" rel="noopener noreferrer">官方协议文档</a><button type="button" :disabled="busy||!selected||config.services.length>=30" @click="addService">添加服务商</button></div>
<article v-for="service in config.services" :key="service.id" class="service"><h3>{{service.name}}</h3><div class="fields"><label>服务商名称<input v-model="service.name" maxlength="80" :disabled="busy"></label><label>协议类型<select v-model="service.kind" :disabled="busy"><option value="openai">OpenAI Compatible</option><option value="ollama">Ollama 原生</option><option value="anthropic">Anthropic Messages</option><option value="gemini">Gemini 原生</option></select></label><label>API Base URL<input v-model="service.base_url" type="url" :disabled="busy"></label><label>密钥环境变量引用<input :value="service.key_env||''" placeholder="LJ_AI_KEY_PRIMARY" :disabled="busy" @input="service.key_env=($event.target as HTMLInputElement).value||null"></label><label>连接超时（秒）<input v-model.number="service.timeout_seconds" type="number" min="5" max="120" :disabled="busy"></label></div>
<div class="actions"><label><input v-model="service.enabled" type="checkbox" :disabled="busy">启用服务商</label><button type="button" class="quiet" :disabled="busy||dirty||!service.enabled||!!fetching" @click="fetchModels(service)">获取模型列表</button><button type="button" class="quiet" :disabled="busy||config.providers.length>=100" @click="addModel(service)">手动添加模型</button><button type="button" class="quiet" :disabled="busy||!!modelsFor(service.id).length" @click="config.services=config.services.filter((s:any)=>s.id!==service.id)">删除空服务商</button></div><p v-if="notices[service.id]" role="status">{{notices[service.id]}}</p>
<label v-if="lists[service.id]?.length">从服务返回的模型中添加<select aria-label="从服务返回的模型中添加" :disabled="busy||config.providers.length>=100" @change="($event.target as HTMLSelectElement).value&&addModel(service,($event.target as HTMLSelectElement).value);($event.target as HTMLSelectElement).value='' "><option value="">请选择（添加后默认停用）</option><option v-for="m in lists[service.id]" :key="m.id" :value="m.id">{{m.name}} · {{m.id}}</option></select></label>
<article v-for="model in modelsFor(service.id)" :key="model.id" class="model"><p>最近连接 / 调用状态：{{calls.find((call:any)=>call.provider_id===model.id)?.state||'尚未测试'}}（仅代表记录状态，非服务商实测认证）</p><div class="fields"><label>模型显示名称<input v-model="model.name" maxlength="80" :disabled="busy"></label><label>模型 ID<input v-model="model.model" maxlength="200" :disabled="busy"></label><label>最大输出 Token<input v-model.number="model.max_output_tokens" type="number" min="64" max="16384" :disabled="busy"></label><label v-if="service.kind==='openai'">输出 Token 参数<select v-model="model.token_parameter" :disabled="busy"><option value="auto">自动（推理使用 max_completion_tokens）</option><option value="max_tokens">max_tokens</option><option value="max_completion_tokens">max_completion_tokens</option><option value="omit">不发送（遵循服务端限制）</option></select></label><label v-if="service.kind==='openai'">指令角色<select v-model="model.system_role" :disabled="busy"><option value="system">system</option><option value="developer">developer</option></select></label><label>24小时调用上限<input v-model.number="model.daily_requests" type="number" min="1" max="1000" :disabled="busy"></label></div><div class="actions"><label><input v-model="model.enabled" type="checkbox" :disabled="busy">启用模型</label><label><input v-model="model.text" type="checkbox" :disabled="busy">文本生成</label><label><input v-model="model.vision" type="checkbox" :disabled="busy">图片理解（需另行发送授权）</label><label><input v-model="model.reasoning" type="checkbox" :disabled="busy">推理模型参数兼容（不发送 temperature，不启用扩展思考预算）</label><label><input v-model="model.json_mode" type="checkbox" :disabled="busy||model.reasoning||service.kind==='anthropic'">原生 JSON 模式（仍须通过内容校验）</label><button type="button" class="quiet" :disabled="busy||dirty||!model.enabled||!service.enabled||!model.text" @click="emit('test',effectiveModels(config).find((p:any)=>p.id===model.id))">测试 / 核对模型连接</button><button type="button" class="quiet" :disabled="busy" @click="removeModel(model.id)">删除模型</button></div></article>
</article>
<h3>各写作任务默认模型</h3><p>停用或删除默认模型后，对应任务须重新选择；不会自动切换服务商或发起调用。</p><p v-if="affected.length" role="alert">默认模型已不可用：{{affected.join('、')}}。请明确重新指定。</p><div class="fields"><label v-for="[key,name] in tasks" :key="key">{{name}}<select :aria-label="name" v-model="config.task_defaults[key]" :disabled="busy"><option :value="undefined">继承已有默认写作模型</option><option :value="null">不预选，调用时手动选择</option><option v-for="model in effectiveModels(config).filter((p:any)=>p.enabled&&p.text!==false)" :key="model.id" :value="model.id">{{model.name}} · {{model.model}}</option></select></label></div>
</section>
</template>
<style scoped>
.services{padding:clamp(16px,3vw,28px);margin-block:20px;min-width:0}.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:12px}.service,.model{border-top:1px solid var(--ui-line);padding-block:16px}.model{margin-inline:8px}.services label{display:block}.services input[type=checkbox]{width:auto}.services .actions{flex-wrap:wrap}.services input,.services select{max-width:100%;box-sizing:border-box}.services p{overflow-wrap:anywhere}
</style>
